// Construye un objeto `response` conforme a Open Responses.
// Envuelve la salida en {__status, cuerpo} para que `Responder` fije el codigo HTTP.

const previo = $input.first().json;

// Si `Autorizar` ya decidio rechazar, se deja pasar su respuesta tal cual.
if (previo.__status !== 200) return [{ json: previo }];

const body = previo.body ?? {};

// `crypto` no existe en el sandbox del task runner de n8n.
// El id solo tiene que ser opaco y unico, no criptografico.
const id = (prefijo) =>
  prefijo + '_' + Date.now().toString(36) + Math.random().toString(36).slice(2, 12);

// ponytail: el ticket #1 solo exige `input` como string.
// El array de items lo cubre el ticket #3.
const texto = typeof body.input === 'string' ? body.input : '';

return [{
  json: {
    __status: 200,
    cuerpo: {
      id: id('resp'),
      object: 'response',
      created_at: Math.floor(Date.now() / 1000),
      status: 'completed',
      model: body.model ?? 'bano',
      output: [
        {
          id: id('msg'),
          type: 'message',
          status: 'completed',
          role: 'assistant',
          content: [{ type: 'output_text', text: 'eco: ' + texto, annotations: [] }],
        },
      ],
      usage: { input_tokens: 0, output_tokens: 0, total_tokens: 0 },
    },
  },
}];

// Compara el bearer recibido contra el guardado en la data table `bano_secretos`.
// El token NUNCA se escribe en el nodo: este JSON se publica en un repo publico.

const turno = $('Webhook').first().json;

const fila = $input.all().map((i) => i.json).find((r) => r.clave === 'bearer_token');
const esperado = fila ? String(fila.valor || '') : '';

const recibido = String(turno.headers?.authorization || '')
  .replace(/^Bearer\s+/i, '')
  .trim();

const fallo = (status, code, message) => [{
  json: {
    __status: status,
    cuerpo: { error: { type: 'invalid_request_error', code, message, param: 'Authorization' } },
  },
}];

// Sin token guardado no se puede autenticar a nadie: culpa del servidor, no del cliente.
if (!esperado) {
  return [{
    json: {
      __status: 500,
      cuerpo: {
        error: {
          type: 'server_error',
          code: 'token_no_configurado',
          message: 'El servidor no tiene configurado el token de acceso.',
          param: null,
        },
      },
    },
  }];
}

if (!recibido) {
  return fallo(401, 'missing_authorization', 'Falta la cabecera Authorization: Bearer <token>.');
}

if (recibido !== esperado) {
  return fallo(401, 'invalid_api_key', 'El token proporcionado no es valido.');
}

return [{ json: { __status: 200, body: turno.body ?? {} } }];
